from pathlib import Path
import base64, gzip, subprocess

PAYLOAD = ''''''

patch = gzip.decompress(base64.b64decode(PAYLOAD))
Path('/tmp/r972.patch').write_bytes(patch)
subprocess.run(['git','apply','--check','/tmp/r972.patch'], check=True)
subprocess.run(['git','apply','/tmp/r972.patch'], check=True)

index = Path('index.html').read_text(encoding='utf-8')
sw = Path('sw.js').read_text(encoding='utf-8')
assert 'R9.7.2' in index
assert 'navegacaoPoliciaisP1' in index
assert 'resumoModuloPoliciaisP1' in index
assert "siga-github-v5.9.0-r9.7.2" in sw
print('R9.7.2 aplicada com sucesso')
